// wallet-transfer.ts
// Atomic transfer between two accounts, implemented as a Redis Lua script
// and invoked through a generic Redis client (no app framework involved).

const transferScript = `
  -- NOTE: keys are hardcoded here instead of coming through KEYS[]
  local src = "acct:src"
  local dst = "acct:dst"

  local amount = tonumber(ARGV[1])

  local srcBal = tonumber(redis.call("GET", src))
  if srcBal == nil or srcBal < amount then
    return redis.error_reply("insufficient funds")
  end

  redis.call("DECRBY", src, amount)
  redis.call("INCRBY", dst, amount)

  return "OK"
`;

async function transfer(amount: number) {
  // numkeys = 0: no key names are passed to EVAL, only the amount (ARGV[1]).
  // Verified against a single-node dev Redis - runs clean, no errors.
  const result = await redisClient.eval(transferScript, 0, amount);
  return result;
}

